const el = id => document.getElementById(id);
const escapeHTML = x => String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const countComments = nodes => nodes.reduce((sum,n)=>sum+1+countComments(n.replies||[]),0);
const fmtDate = ts => `${Number(ts.slice(5,7))}월 ${Number(ts.slice(8,10))}일 ${ts.slice(11,16)}`;
const fmtNum = n => Number(n).toLocaleString('ko-KR');
const sorted = [...POSTS].sort((a,b)=>b.ts.localeCompare(a.ts));
const hot = [...POSTS].sort((a,b)=>(b.likes + countComments(b.comments)*12)-(a.likes+countComments(a.comments)*12)).slice(0,3);
const KEY='uwp-du-votes-v4';
let votes={};
try { const data=JSON.parse(localStorage.getItem(KEY)||'{}'); if(data&&typeof data==='object') votes=data; } catch(e) {}
const voteBases=new Map();
function seedScore(key){ let h=2166136261; for(const ch of key){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0; }
function getBase(key, post=null){
  if(!voteBases.has(key)){
    const h=seedScore(key);
    voteBases.set(key,post?{up:post.likes,down:Math.max(0,Math.round(post.likes*(.015+(h%7)/200)))}:
      {up:h%17===0?30+h%94:h%5===0?8+h%23:h%7,down:h%13===0?2+h%5:h%11===0?1:0});
  }
  return voteBases.get(key);
}
function getCounts(key,post=null){ const base=getBase(key,post), val=votes[key]===1?1:votes[key]===-1?-1:0;return {up:base.up+(val===1?1:0),down:base.down+(val===-1?1:0),val}; }
function voteBar(key,post=null,kind='comment'){
  const c=getCounts(key,post);
  return `<div class="vote-bar ${kind==='post'?'post-vote':'comment-vote'}" aria-label="추천 및 비추천">
    <button type="button" class="vote-button up ${c.val===1?'chosen':''}" aria-label="추천 ${fmtNum(c.up)}개" aria-pressed="${c.val===1}" data-vote-key="${key}" data-vote="1"><span aria-hidden="true">▲</span><span>추천</span><strong>${fmtNum(c.up)}</strong></button>
    <button type="button" class="vote-button down ${c.val===-1?'chosen':''}" aria-label="비추천 ${fmtNum(c.down)}개" aria-pressed="${c.val===-1}" data-vote-key="${key}" data-vote="-1"><span aria-hidden="true">▼</span><span>비추천</span><strong>${fmtNum(c.down)}</strong></button>
  </div>`;
}
function updateVote(key, direction){
  votes[key]=votes[key]===direction?0:direction;
  try {localStorage.setItem(KEY,JSON.stringify(votes));}catch(e){}
  const c=getCounts(key);
  document.querySelectorAll('[data-vote-key]').forEach(button=>{
    if(button.dataset.voteKey!==key)return;
    const d=Number(button.dataset.vote);
    const selected=c.val===d;
    button.classList.toggle('chosen',selected);
    button.setAttribute('aria-pressed',String(selected));
    const n=d===1?c.up:c.down;
    button.querySelector('strong').textContent=fmtNum(n);
    button.setAttribute('aria-label',`${d===1?'추천':'비추천'} ${fmtNum(n)}개`);
  });
  if(key.endsWith(':p')){
    const id=Number(key.split(':')[1]);
    document.querySelectorAll(`[data-post-likes="${id}"]`).forEach(n=>n.textContent=fmtNum(c.up));
  }
}
let filter='전체',search='',activePost=null,visible=18,prevFocus=null;
function renderHot(){
 el('hot-list').innerHTML=hot.map((p,i)=>`<button class="hot-card" data-id="${p.id}"><span class="hot-rank">HOT ${i+1}</span><strong>${escapeHTML(p.title)}</strong><span class="hot-meta">${escapeHTML(p.cat)} · 추천 <span data-post-likes="${p.id}">${fmtNum(getCounts(`post:${p.id}:p`,p).up)}</span> · 댓글 ${fmtNum(countComments(p.comments))}</span></button>`).join('');
}
function renderFeed(){
 const list=sorted.filter(p=>(filter==='전체'||p.cat===filter)&&([p.title,p.body,p.cat].join(' ').toLowerCase().includes(search.toLowerCase())));
 el('feed-status').textContent=`최신 글 · ${list.length}개`;
 el('posts').innerHTML=list.length?list.map(p=>`<article class="post"><button class="post-open" data-id="${p.id}"><div class="meta"><span class="tag">${escapeHTML(p.cat)}</span><span>익명</span><time>${fmtDate(p.ts)}</time></div><strong>${escapeHTML(p.title)}</strong><div class="excerpt">${escapeHTML(p.body)}</div></button><div class="post-bottom">${voteBar(`post:${p.id}:p`,p,'post')}<div class="post-stats"><span>댓글 ${fmtNum(countComments(p.comments))}</span><span>조회 ${fmtNum(p.views)}</span></div></div></article>`).join(''):'<div class="nothing">해당하는 게시글이 없어.</div>';
}
function renderComment(node,path,depth=0){
 const replies=node.replies||[];
 // Expand common short conversations immediately; only very long branches collapse.
 const limit=depth===0?7:depth===1?6:5;
 const direct=replies.slice(0,limit),hidden=replies.slice(limit);
 const key=`post:${activePost.id}:c:${path}`;
 return `<article class="comment" data-comment-path="${path}">
   <div class="author"><span>${escapeHTML(node.author)}</span>${replies.length?`<span class="reply-quantity">답글 ${fmtNum(countComments(replies))}</span>`:''}</div>
   <p>${escapeHTML(node.text)}</p>
   ${voteBar(key,null,'comment')}
   ${direct.length?`<div class="replies">${direct.map((n,i)=>renderComment(n,`${path}.${i}`,depth+1)).join('')}</div>`:''}
   ${hidden.length?`<button class="more" data-reveal="${path}" aria-expanded="false">↳ 답글 ${fmtNum(countComments(hidden))}개 더 보기</button><div class="replies extra-replies" hidden>${hidden.map((n,i)=>renderComment(n,`${path}.${limit+i}`,depth+1)).join('')}</div>`:''}
 </article>`;
}
function showCommentPage(){
 const p=activePost;if(!p)return;
 const roots=p.comments;
 el('comments').innerHTML=roots.slice(0,visible).map((n,i)=>renderComment(n,String(i))).join('');
 const rest=roots.length-visible;
 el('load-more').hidden=rest<=0;
 el('load-more').textContent=rest>0?`댓글 더 보기 (${fmtNum(rest)}개 스레드 남음)`:'';
}
function openPost(id){
 const p=POSTS.find(x=>x.id===id);if(!p)return;
 prevFocus=document.activeElement;activePost=p;visible=18;
 el('detail').innerHTML=`<section class="detail-head"><div class="tag">${escapeHTML(p.cat)}</div><div class="detail-date">익명 · ${fmtDate(p.ts)} · 조회 ${fmtNum(p.views)}</div><h2 id="detail-title">${escapeHTML(p.title)}</h2><p>${escapeHTML(p.body)}</p>${voteBar(`post:${p.id}:p`,p,'post')}</section><div class="comment-header">댓글 <span>${fmtNum(countComments(p.comments))}</span>개 <small>답글 포함</small></div><div id="comments"></div><button id="load-more" class="pager" hidden></button>`;
 showCommentPage();el('overlay').hidden=false;document.body.style.overflow='hidden';el('dialog').scrollTop=0;el('close').focus();
}
function closePost(){el('overlay').hidden=true;document.body.style.overflow='';activePost=null;if(prevFocus&&prevFocus.focus)prevFocus.focus();}
el('categories').addEventListener('click',e=>{const btn=e.target.closest('button[data-cat]');if(!btn)return;filter=btn.dataset.cat;el('categories').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===btn));renderFeed();});
el('search').addEventListener('input',e=>{search=e.target.value.trim();renderFeed();});
document.addEventListener('click',e=>{
 const vote=e.target.closest('button[data-vote]');if(vote){updateVote(vote.dataset.voteKey,Number(vote.dataset.vote));return;}
 const post=e.target.closest('[data-id]');if(post){openPost(Number(post.dataset.id));return;}
 const reveal=e.target.closest('button[data-reveal]');if(reveal){const group=reveal.nextElementSibling;if(group){group.hidden=false;reveal.remove();}return;}
 if(e.target.id==='load-more'){visible+=18;showCommentPage();return;}
 if(e.target.id==='close'||e.target.id==='overlay'){closePost();}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!el('overlay').hidden)closePost();});
renderHot();renderFeed();
